function openAuthModal(){soundClick();const modal=document.getElementById("authModal");const loggedSection=document.getElementById("authLoggedInSection");const formSection=document.getElementById("authFormSection");authToken=loadFromStorage(STORAGE_KEYS.TOKEN,null);authUser=loadFromStorage(STORAGE_KEYS.AUTH,null);if(authToken&&authUser){loggedSection.style.display="block";formSection.style.display="none";document.getElementById("authUserName").textContent=authUser.username;if(authUser.is_admin){document.getElementById("authRoleBadge").textContent="👑 首席管理员 (Admin · 拥有全部额度与后台特权)"}else if(authUser.can_use_quota){document.getElementById("authRoleBadge").textContent="⚡ 探险生还者 (User · 站长已授权使用 AI 额度)"}else{document.getElementById("authRoleBadge").textContent="👤 探险生还者 (User · 离线矩阵保底)"}document.getElementById("adminLaunchBtn").style.display=authUser.is_admin?"block":"none"}else{loggedSection.style.display="none";formSection.style.display="block"}modal.style.display="block";setTimeout(()=>modal.style.opacity="1",10)}function closeAuthModal(){const modal=document.getElementById("authModal");modal.style.opacity="0";setTimeout(()=>modal.style.display="none",200)}function switchAuthTab(mode){authTabMode=mode;document.getElementById("tabAuthLogin").classList.toggle("active",mode==="login");document.getElementById("tabAuthReg").classList.toggle("active",mode==="reg");document.getElementById("grpRegApiKey").style.display=mode==="reg"?"block":"none";document.getElementById("authSubmitBtn").textContent=mode==="login"?"🔑 立即登录":"✨ 注册新账号"}async function handleAuthSubmit(){const u=document.getElementById("authInputUser").value.trim();const p=document.getElementById("authInputPass").value.trim();const k=document.getElementById("authInputApiKey").value.trim();if(!u||!p){showToast("⚠️ 请输入用户名和密码");return}const submitBtn=document.getElementById("authSubmitBtn");submitBtn.disabled=true;submitBtn.textContent="⏳ 正在同步云端档案...";try{const endpoint=authTabMode==="login"?"/api/login":"/api/register";const payload=authTabMode==="login"?{username:u,password:p}:{username:u,password:p,custom_api_key:k};const resp=await fetch(API_BASE+endpoint,{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(payload)});const data=await resp.json();if(!resp.ok)throw new Error(data.detail||"操作失败，请检查账号密码");saveToStorage(STORAGE_KEYS.TOKEN,data.token);saveToStorage(STORAGE_KEYS.AUTH,data.user);authToken=data.token;authUser=data.user;window.location.reload();return;closeAuthModal();showToast(`🎉 欢迎回来，${authUser.username}！云端档案已同步`)}catch(e){showToast(`❌ ${e.message}`)}finally{submitBtn.disabled=false;submitBtn.textContent=authTabMode==="login"?"🔑 立即登录":"✨ 注册新账号"}}function logoutUser(){StoneStorage.removeItem(STORAGE_KEYS.TOKEN);StoneStorage.removeItem(STORAGE_KEYS.AUTH);authToken=null;authUser=null;updateAuthUI();closeAuthModal();window.location.reload()}function updateAuthUI(){const btnName=document.getElementById("userBtnName");const adminBadgeBtn=document.getElementById("topAdminBtn");const adminLaunchBtn=document.getElementById("adminLaunchBtn");authToken=loadFromStorage(STORAGE_KEYS.TOKEN,null);authUser=loadFromStorage(STORAGE_KEYS.AUTH,null);if(adminBadgeBtn){adminBadgeBtn.style.display="inline-flex"}if(authToken&&authUser){btnName.textContent=authUser.username;const isMasterAdmin=Boolean(authUser.is_admin||authUser.role==="admin"||["林允安","允安"].includes(authUser.username));if(adminBadgeBtn){adminBadgeBtn.textContent=isMasterAdmin?"👑 控制台 (Admin)":"👑 控制台"}if(adminLaunchBtn){adminLaunchBtn.style.display=isMasterAdmin?"block":"none"}}else{btnName.textContent="登录";if(adminBadgeBtn){adminBadgeBtn.textContent="👑 控制台"}if(adminLaunchBtn){adminLaunchBtn.style.display="none"}}}